-- Run inside a transaction with the two migrations, and ALWAYS roll back.
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();native uuid;created uuid;p jsonb;r jsonb;name text:='px_'||substr(replace(gen_random_uuid()::text,'-',''),1,16);
 email text;h text:=repeat('a',64);failed boolean;keys integer;g bigint;
begin
 email:=name||'@example.invalid';
 perform app_private.pixel_attempt_begin(repeat('b',64),repeat('c',64),repeat('v',43),repeat('n',43),'create',null);
 r:=app_private.pixel_attempt_take(repeat('b',64),repeat('c',64));
 if r->>'intent'<>'create' then raise exception 'Attempt mismatch';end if;
 failed:=false;begin perform app_private.pixel_attempt_take(repeat('b',64),repeat('c',64));exception when others then failed:=true;end;
 if not failed then raise exception 'Attempt replay was accepted';end if;
 p:=app_private.pixel_bind_account(a,name,email,false,null,h,'create');created:=(p->>'user_id')::uuid;
 if created is null or created=a or p->>'username'<>name or(p->>'email_verified')::boolean then raise exception 'New identity or verification mismatch';end if;
 select count(*) into keys from public.player_unlocks where user_id=created and item_type='character';
 if keys<>4 then raise exception 'New account must have exactly four starters, got %',keys;end if;
 if exists(select 1 from public.admin_users where user_id=created) then raise exception 'New SSO account received an admin role';end if;
 perform app_private.pixel_session_revoke(h);
 if app_private.pixel_session_get(h) is not null then raise exception 'Session survived sign-out';end if;
 p:=app_private.pixel_bind_account(a,name,email,false,null,repeat('d',64),'sign-in');
 if (p->>'user_id')::uuid<>created then raise exception 'Repeat SSO created another game account';end if;
 failed:=false;begin update public.player_profiles set username=name||'x' where user_id=created;exception when others then failed:=true;end;
 if not failed then raise exception 'Shared username changed independently';end if;
 insert into neon_auth."user"(name,email,"emailVerified") values(name||'n',name||'n@example.invalid',true) returning id into native;
 update public.player_stats set total_gems=37,high_score=12345 where user_id=native;
 failed:=false;begin perform app_private.pixel_bind_account(b,name||'n',name||'n@example.invalid',true,null,repeat('e',64),'create');exception when others then failed:=true;end;
 if not failed then raise exception 'Email-only account linking was accepted';end if;
 p:=app_private.pixel_bind_account(b,name||'n',name||'n@example.invalid',true,native,repeat('e',64),'link');
 if (p->>'user_id')::uuid<>native then raise exception 'Existing game account UUID changed';end if;
 select total_gems into g from public.player_stats where user_id=native;
 if g<>37 or(select high_score from public.player_stats where user_id=native)<>12345 then raise exception 'Existing stats changed during linking';end if;
 failed:=false;begin perform app_private.pixel_bind_account(a,name,email,false,native,repeat('f',64),'link');exception when others then failed:=true;end;
 if not failed then raise exception 'Central identity linked to two game accounts';end if;
 if has_function_privilege('authenticated','app_private.pixel_bind_account(uuid,text,text,boolean,uuid,text,text)','execute')
  or has_function_privilege('anon','public.get_my_pixel_identity()','execute')
  or has_table_privilege('authenticated','app_private.pixel_sessions','select') then raise exception 'Private identity access leaked';end if;
end $test$;
do $management$
declare s uuid:=gen_random_uuid();other uuid:=gen_random_uuid();native uuid;fresh uuid;r jsonb;failed boolean;
 n text:='pa_'||substr(replace(gen_random_uuid()::text,'-',''),1,12);e text;before jsonb;
begin
 e:=n||'@example.invalid';
 insert into neon_auth."user"(name,email,"emailVerified") values(n,e,false) returning id into native;
 update public.player_stats set total_gems=29,high_score=9876 where user_id=native;
 select to_jsonb(t) into before from public.player_stats t where user_id=native;
 if app_private.pixel_account_status(s,e,false)->>'state'<>'verification_required' then raise exception 'Unverified email probed a legacy match';end if;
 r:=app_private.pixel_account_status(s,e,true);
 if r->>'state'<>'link_required' or r ? 'localAccountId' then raise exception 'Status leaked a legacy account ID';end if;
 failed:=false;begin perform app_private.pixel_bind_account_v2(s,n,e,true,null,repeat('1',64),'sign-in',0,0,true);exception when others then failed:=true;end;
 if not failed then raise exception 'Unverified native account auto-linked';end if;
 update neon_auth."user" set "emailVerified"=true where id=native;
 failed:=false;begin perform app_private.pixel_bind_account_v2(s,n,e,false,null,repeat('1',64),'sign-in',0,0,true);exception when others then failed:=true;end;
 if not failed then raise exception 'Unverified central claim auto-linked';end if;
 r:=app_private.pixel_bind_account_v2(s,n,e,true,null,repeat('1',64),'sign-in',0,0,true);
 if (r->>'user_id')::uuid<>native then raise exception 'Verified adoption duplicated the game ID';end if;
 if (select to_jsonb(t) from public.player_stats t where user_id=native)<>before then raise exception 'Adoption changed game stats';end if;
 r:=app_private.pixel_sync_identity(s,n||' spaced',e,true,1,0);
 if r->>'state'<>'linked' or (r->>'profileVersion')::int<>1 then raise exception 'Profile update not acknowledged';end if;
 if (select username from public.player_profiles where user_id=native)<>n||' spaced' or (select name from neon_auth."user" where id=native)<>n||' spaced' then raise exception 'Canonical name was not persisted';end if;
 failed:=false;begin perform app_private.pixel_sync_identity(s,n,e,true,0,0);exception when others then failed:=true;end;
 if not failed then raise exception 'Stale profile overwrote the current name';end if;
 failed:=false;begin perform app_private.pixel_sync_identity(s,n,e,true,1,0);exception when others then failed:=true;end;
 if not failed then raise exception 'Same-version conflicting profile was accepted';end if;
 failed:=false;begin perform app_private.pixel_sync_identity(s,n||' spaced',n||'new@example.invalid',false,2,0);exception when others then failed:=true;end;
 if not failed then raise exception 'Unverified new email replaced a verified address';end if;
 perform app_private.pixel_sync_identity(s,n||' spaced',n||'new@example.invalid',true,2,1);
 if (select email from neon_auth."user" where id=native)<>n||'new@example.invalid' or not(select "emailVerified" from neon_auth."user" where id=native) then raise exception 'Verified canonical email did not reach native storage';end if;
 failed:=false;begin update neon_auth."user" set name='different native name' where id=native;exception when others then failed:=true;end;
 if not failed then raise exception 'Native update bypassed canonical-name guard';end if;
 if app_private.pixel_session_get(repeat('1',64)) is not null then raise exception 'Old credential-version session survived';end if;
 failed:=false;begin perform app_private.pixel_bind_account_v2(s,n||' spaced',n||'new@example.invalid',true,null,repeat('6',64),'sign-in',2,0,true);exception when others then failed:=true;end;
 if not failed or app_private.pixel_session_get(repeat('6',64)) is not null then raise exception 'Missing/stale credential epoch created a fresh session';end if;
 perform app_private.pixel_bind_account_v2(s,n||' spaced',n||'new@example.invalid',true,null,repeat('7',64),'sign-in',2,1,true);
 r:=app_private.pixel_retire_credentials(s,2);
 if (r->>'credentialVersion')::int<>2 or app_private.pixel_session_get(repeat('7',64)) is not null then raise exception 'Owned credential retirement did not expire old sessions';end if;
 failed:=false;begin perform app_private.pixel_sync_identity(s,n||' spaced',n||'unverified@example.invalid',false,3,2);exception when others then failed:=true;end;
 if not failed or (select credential_version from app_private.pixel_links where subject=s)<>2 or (select email from neon_auth."user" where id=native)<>n||'new@example.invalid' then raise exception 'Blocked profile rolled back security retirement or changed native email';end if;
 if app_private.pixel_retire_credentials(gen_random_uuid(),99) is not null then raise exception 'Unknown subject was mapped during security retirement';end if;
 failed:=false;begin perform app_private.pixel_management_bind(s,n||' spaced',n||'new@example.invalid',true,2,1,'create',null,repeat('2',64));exception when others then failed:=true;end;
 if not failed then raise exception 'Create made a duplicate of a linked account';end if;
 if app_private.pixel_account_status(other,n||'new@example.invalid',true)->>'state'<>'conflict' then raise exception 'Email belonging to another subject was linkable';end if;
 r:=app_private.pixel_management_bind(other,n||' fresh',n||'fresh@example.invalid',true,0,0,'create',null,repeat('3',64));fresh:=(r->>'localAccountId')::uuid;
 if r->>'state'<>'linked' or fresh is null then raise exception 'Creation did not return a committed binding';end if;
 if app_private.pixel_session_get(repeat('3',64)) is not null then raise exception 'Management endpoint left an unusable session';end if;
 if (select count(*) from public.player_unlocks where user_id=fresh and item_type='character')<>4 then raise exception 'Management creation unlocked the catalog';end if;
 if not app_private.pixel_ticket_take(repeat('4',64),clock_timestamp()+interval '60 seconds') or app_private.pixel_ticket_take(repeat('4',64),clock_timestamp()+interval '60 seconds') then raise exception 'Mutation ticket replay guard failed';end if;
 if app_private.pixel_ticket_take(repeat('5',64),clock_timestamp()-interval '1 second') then raise exception 'Expired ticket was accepted';end if;
 if has_function_privilege('authenticated','app_private.pixel_retire_credentials(uuid,bigint)','execute') or has_function_privilege('authenticated','app_private.pixel_sync_identity(uuid,text,text,boolean,bigint,bigint)','execute') or has_table_privilege('anonymous','app_private.pixel_management_tickets','select') then raise exception 'Management privileges escaped the backend';end if;
end $management$;
select 'Pixel identity, proof linking, retries, starters, currencies and access controls passed' as verification;
